import{_ as a,o as d,c as e,ah as r}from"./chunks/framework.Yx0DUrwu.js";const b=JSON.parse('{"title":"黏膜免疫、疾病与治疗","description":"","frontmatter":{},"headers":[],"relativePath":"biology/mucosal-disease-immunotherapy.md","filePath":"biology/mucosal-disease-immunotherapy.md","lastUpdated":1787830595000}'),o={name:"biology/mucosal-disease-immunotherapy.md"};function i(l,t,h,c,n,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="黏膜免疫、疾病与治疗" tabindex="-1">黏膜免疫、疾病与治疗 <a class="header-anchor" href="#黏膜免疫、疾病与治疗" aria-label="Permalink to &quot;黏膜免疫、疾病与治疗&quot;">​</a></h1><p>免疫系统既要清除威胁，也要避免对自身组织、食物抗原和共生微生物产生过度反应。黏膜免疫、免疫缺陷、过敏、自身免疫、移植、疫苗和肿瘤免疫治疗，本质上都围绕这个平衡展开 [1]。</p><h2 id="黏膜免疫" tabindex="-1">黏膜免疫 <a class="header-anchor" href="#黏膜免疫" aria-label="Permalink to &quot;黏膜免疫&quot;">​</a></h2><p>黏膜是免疫系统最繁忙的界面之一：它持续接触食物、空气、共生菌和病原体。黏膜免疫的重点不是“一直强烈炎症”，而是屏障保护、IgA、组织驻留细胞、微生物群调控和口服耐受的平衡。</p><table tabindex="0"><thead><tr><th>模块</th><th>功能</th><th>单细胞线索</th></tr></thead><tbody><tr><td>上皮屏障</td><td>物理隔离、抗菌分子、危险信号释放。</td><td>上皮应激、<code>DEFA*</code>, <code>REG*</code>、干扰素相关基因。</td></tr><tr><td>分泌型 IgA</td><td>中和和限制微生物黏附，降低炎症性清除需求。</td><td><code>JCHAIN</code>, <code>IGHA1</code>, <code>IGHA2</code>、浆细胞。</td></tr><tr><td>组织驻留淋巴细胞</td><td>快速局部保护与组织监视。</td><td><code>ITGAE</code>, <code>CXCR6</code>, <code>ZNF683</code>, <code>CD69</code>。</td></tr><tr><td>微生物群调控</td><td>塑造局部和系统免疫状态。</td><td>髓系细胞活化、Th17/ILC3 程序、屏障基因。</td></tr></tbody></table><h2 id="免疫防御失败" tabindex="-1">免疫防御失败 <a class="header-anchor" href="#免疫防御失败" aria-label="Permalink to &quot;免疫防御失败&quot;">​</a></h2><p>免疫缺陷可以来自遗传缺陷、感染、药物、营养、年龄或治疗造成的继发性免疫抑制。不同缺陷对应不同感染谱：</p><table tabindex="0"><thead><tr><th>缺陷类型</th><th>易感问题</th><th>机制理解</th></tr></thead><tbody><tr><td>T 细胞/联合免疫缺陷</td><td>病毒、真菌、机会性感染</td><td>T 细胞辅助、细胞毒性和免疫协调不足。</td></tr><tr><td>B 细胞/抗体缺陷</td><td>胞外细菌、部分病毒</td><td>中和、调理作用和补体活化不足。</td></tr><tr><td>吞噬细胞缺陷</td><td>细菌和真菌播散</td><td>摄取、氧爆发或趋化迁移不足。</td></tr><tr><td>补体缺陷</td><td>荚膜细菌、免疫复合物病</td><td>调理作用、裂解和免疫复合物清除不足。</td></tr></tbody></table><h2 id="过敏和超敏反应" tabindex="-1">过敏和超敏反应 <a class="header-anchor" href="#过敏和超敏反应" aria-label="Permalink to &quot;过敏和超敏反应&quot;">​</a></h2><p>过敏可以理解为免疫系统对无害抗原产生了过强或错误类型的效应应答。在 IgE 介导的过敏中，Th2/Tfh 信号推动 IgE 产生；IgE 固定在肥大细胞和嗜碱性粒细胞的 Fc epsilon 受体上，再次遇到变应原时快速脱颗粒。</p><div class="check-grid"><article><strong>IgE / 肥大细胞轴</strong><span>快速释放组胺、脂质介质和细胞因子，造成鼻炎、哮喘、荨麻疹或过敏性休克。</span></article><article><strong>嗜酸性粒细胞</strong><span>参与寄生虫防御，也可在过敏性炎症中造成组织损伤。</span></article><article><strong>免疫复合物</strong><span>大量难清除抗原-抗体复合物可诱发补体和炎症损伤。</span></article><article><strong>迟发型超敏反应</strong><span>Th1 和 CD8 T 细胞可介导迟发型组织炎症。</span></article></div><h2 id="自身免疫和移植" tabindex="-1">自身免疫和移植 <a class="header-anchor" href="#自身免疫和移植" aria-label="Permalink to &quot;自身免疫和移植&quot;">​</a></h2><p>自身免疫来自耐受机制被突破：遗传易感、MHC、感染、组织损伤、分子模拟、免疫豁免区暴露、随机克隆事件都可能参与。移植免疫则是免疫系统把同种异体 MHC 或其呈递的抗原肽识别为危险信号。</p><table tabindex="0"><thead><tr><th>场景</th><th>核心机制</th><th>单细胞关注点</th></tr></thead><tbody><tr><td>器官特异性自身免疫</td><td>自身抗原局部靶向。</td><td>自身反应性 T/B 细胞、组织驻留炎症。</td></tr><tr><td>系统性自身免疫</td><td>免疫复合物、广泛炎症和多器官损伤。</td><td>浆母细胞扩增、干扰素程序、髓系细胞活化。</td></tr><tr><td>急性排斥</td><td>T 细胞介导的同种异体反应。</td><td>细胞毒性 T 细胞、抗原提呈细胞活化、内皮炎症。</td></tr><tr><td>慢性排斥</td><td>持续低度损伤、血管和纤维化改变。</td><td>巨噬细胞、成纤维细胞和内皮细胞状态。</td></tr></tbody></table><h2 id="疫苗和肿瘤免疫治疗" tabindex="-1">疫苗和肿瘤免疫治疗 <a class="header-anchor" href="#疫苗和肿瘤免疫治疗" aria-label="Permalink to &quot;疫苗和肿瘤免疫治疗&quot;">​</a></h2><p>疫苗的目标是安全地产生长期保护性免疫，通常需要抗原、合适的递送方式、佐剂和记忆细胞形成。肿瘤免疫治疗则利用或增强抗肿瘤免疫，包括单克隆抗体、免疫检查点阻断、CAR-T 细胞和肿瘤疫苗。</p><div class="doc-callout important"><strong>肿瘤免疫治疗看的是系统</strong><p>免疫检查点阻断是否有效，不只取决于 T 细胞是否表达 PD-1，还取决于抗原提呈、T 细胞浸润、Treg 和髓系抑制、肿瘤抗原负荷、空间排斥和组织代谢环境。</p></div><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>黏膜免疫为什么必须同时容忍共生菌和清除病原体？</li><li>不同免疫缺陷为什么对应不同感染谱？</li><li>IgE 介导的过敏中，致敏阶段和效应阶段有什么区别？</li><li>免疫检查点阻断为什么不是只看 <code>PDCD1</code> 或 <code>CD274</code> 表达？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',21)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
